-- Node: apap-dialysis (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Hemodialysis — EXTRIP Guidelines","body":"Hemodialysis removes both **APAP and toxic NAPQI metabolites**. May be beneficial in massive poisoning where NAC alone is inadequate. [9]\n\n**EXTRIP criteria for extracorporeal treatment (ECTR):** [9]\n• APAP **>1000 mg/L** (6620 µmol/L) and NAC **not** given\n• Altered mental status + metabolic acidosis + elevated lactate, with APAP **>700 mg/L** (4630 µmol/L) and NAC **not** given\n• Altered mental status + metabolic acidosis + elevated lactate, with APAP **>900 mg/L** (5960 µmol/L) **even if NAC given**\n• NOT recommended on reported dose alone, or on APAP level alone when NAC has been given\n• Intermittent HD preferred; continue until sustained clinical improvement; continue NAC during ECTR at an increased rate\n\n⚠️ **Hemodialysis is NOT a substitute for NAC.** Patients on dialysis require **HIGHER NAC doses** because HD removes ~50% of NAC. Minimum 12.5 mg/kg/hr during intermittent HD. [6][9]\n\n**Coordinate with nephrology early** for massive ingestions. Continuous renal replacement therapy (CRRT) is an alternative if hemodynamically unstable.\n\n⚠️ **Basis disclosure — read the source before acting.** EXTRIP grades these **1D or 2D (very low quality evidence)**; the general ECTR suggestion in severe poisoning is 2D, derived from 24 articles (1 RCT, 1 observational study, 2 PK studies, 20 case reports/series). EXTRIP''s concentration thresholds are explicitly conditioned on whether NAC has been given and on the presence of mitochondrial dysfunction: >1000 mg/L if NAC not administered; >700 mg/L with signs of mitochondrial dysfunction if NAC not administered; >900 mg/L with signs of mitochondrial dysfunction if NAC is administered. Intermittent hemodialysis is the preferred modality. Confirm the applicable threshold against citation 9 and discuss with toxicology/poison control before initiating ECTR. [9]","citation":[6,9],"next":"apap-hepatic-failure"}'::jsonb
WHERE id = 'apap-dialysis' AND tree_id = 'acetaminophen';

