-- Node: hemo-vwd-menorrhagia (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":5,"title":"vWD Menorrhagia Management","body":"**First-line:** Hormonal contraceptives (oral contraceptive pills) [3]\n\n**Adjunctive therapies:**\n• [Desmopressin (DDAVP)](#/drug/desmopressin/von willebrand) — if documented responder\n• [Aminocaproic Acid](#/drug/aminocaproic-acid/hemophilia mucosal) 50–60 mg/kg q6h (max 5 g) × 5–7 days\n• OR [Tranexamic Acid](#/drug/tranexamic-acid/hemophilia mucosal) 10–15 mg/kg PO q8–12h\n\n**⚠️ Check urinalysis before starting antifibrinolytics** — contraindicated with hematuria. [3]\n\n**Menorrhagia definition:** Bleeding >7 days OR >80 mL blood loss per cycle. [10]\n\nMenorrhagia may be the first or only sign of vWD in adolescent females. [1]\n\n**Family screening:** Consider testing family members for bleeding disorders given autosomal inheritance. [3]","citation":[1,3,4,10],"recommendation":"Hormonal contraceptives first-line. Add DDAVP and/or antifibrinolytics as adjuncts. Screen family members.","treatment":{"firstLine":{"drug":"Hormonal Contraceptives (OCPs)","dose":"Standard oral contraceptive regimen","route":"PO","frequency":"Daily (per OCP regimen)","duration":"Ongoing","notes":"First-line therapy for vWD menorrhagia. May be only sign of vWD in adolescent females."},"alternative":{"drug":"Aminocaproic Acid","dose":"50-60 mg/kg (max 5 g/dose)","route":"PO","frequency":"q6h","duration":"5-7 days during menses","notes":"Check urinalysis first - contraindicated with hematuria."},"otherOption":{"drug":"Tranexamic Acid","dose":"10-15 mg/kg","route":"PO","frequency":"q8-12h","duration":"5-7 days during menses","notes":"Alternative antifibrinolytic. Same hematuria contraindication."},"monitoring":"Check urinalysis before antifibrinolytics. Consider DDAVP if documented responder. Screen family members."},"confidence":"recommended","summary":"vWD menorrhagia: TXA + OCP first-line, DDAVP or vWF concentrate for severe cases","skippable":true}'::jsonb
