-- Node: ich-location (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":4,"title":"Hematoma Location","body":"Hematoma location determines surgical approach and prognosis.\n\n**Supratentorial (most common):**\n• Basal ganglia/external capsule (60–65%)\n• Thalamus (15–20%)\n• Lobar (cortical)\n\n**Infratentorial:**\n• Cerebellar (5–10%) — unique urgency\n• Pontine (5%) — poor prognosis regardless\n\n**Intraventricular extension** occurs in >40% and worsens prognosis.","citation":[1,3],"options":[{"label":"Supratentorial","description":"Basal ganglia, thalamic, or lobar hemorrhage","next":"ich-supra-surg"},{"label":"Cerebellar","description":"Posterior fossa — risk of brainstem compression","next":"ich-cerebellar-surg","urgency":"critical"},{"label":"Brainstem (pontine)","description":"Usually non-surgical — supportive care, EVD if hydrocephalus","next":"ich-seizures"},{"label":"Significant Intraventricular Hemorrhage","description":"Blood in ventricles ± hydrocephalus","next":"ich-ivh-evd","urgency":"urgent"}],"summary":"Location guides neurosurgical consultation: supratentorial vs cerebellar vs brainstem vs intraventricular"}'::jsonb
WHERE id = 'ich-location' AND tree_id = 'ich';

-- Node: ich-supra-surg (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Supratentorial Hematoma","body":"**Evidence for surgical evacuation is limited:**\n\n**STICH Trial** (1,033 patients): No benefit from early surgery overall. Possible trend toward benefit for hematomas within 1 cm of cortical surface and lobar hemorrhage with GCS 9–12.\n\n**STICH II Trial** (601 patients): Focused on predicted surgical benefit subgroup — still no significant difference vs conservative management.\n\n**Possible indications for craniotomy:**\n• Large hematoma with significant midline shift\n• Elevated ICP refractory to medical management\n• Hemorrhage secondary to resectable lesion (AVM, tumor)\n• Lobar location, no IVH extension, very early presentation\n\n**Emerging:** Minimally invasive surgery (MISTIE III) — may be more promising than traditional craniotomy.\n\n**Decompressive hemicraniectomy:** Consider for massive edema with impending herniation when other options exhausted.\n\nConsult neurosurgery for all supratentorial ICH — even if medical management planned initially.\n\n**Basis for the MISTIE statement:** MISTIE III was an open-label, blinded-endpoint phase 3 trial at 78 hospitals in supratentorial ICH ≥30 mL, randomising image-guided catheter evacuation plus alteplase 1.0 mg q8h (up to 9 doses, targeting residual clot ≤15 mL) vs standard medical care; it did not meet its primary functional-outcome endpoint [25]. **Basis for the craniotomy indications listed above:** AHA/ASA 2022 [1] and ESO/EANS 2025 [2], which grade routine early craniotomy for supratentorial ICH as not beneficial, reserving surgery for deterioration or life-threatening mass effect.","citation":[1,2,9,10,11,25],"next":"ich-seizures","summary":"Supratentorial ICH: neurosurgery for large (>30mL), superficial, or deteriorating — deep basal ganglia usually conservative"}'::jsonb
WHERE id = 'ich-supra-surg' AND tree_id = 'ich';

-- Node: mening-tx-crypto (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Empiric: Suspected Cryptococcal","body":"**Cryptococcal meningitis** is the 2nd highest cause of mortality in HIV/AIDS patients. *C. neoformans* causes ~1 million cases/year in HIV/AIDS, with ~600,000 annual deaths. [17]\n\nTypically subacute: weeks of evolving headache, neck stiffness, malaise.\n\n**Serum cryptococcal antigen (CrAg):** 99.7% sensitive, 94.1% specific — send immediately. [17]\n\n**Empiric antifungal regimen (after ID consultation):**\n• [Amphotericin B liposomal](#/drug/amphotericin-b/cryptococcal meningitis) 3–4 mg/kg/day IV [22,30]\n• [Flucytosine](#/drug/flucytosine/cryptococcal meningitis) 25 mg/kg PO q6h [22,30]\n• Induction × 1 week, then [Fluconazole](#/drug/fluconazole/cryptococcal meningitis) 400–800 mg/day [22,30]\n\n**ALSO give empiric bacterial coverage** (Ceftriaxone + Vancomycin + Ampicillin) until CSF results available. [1,27]\n\n**⚠️ Do NOT give corticosteroids** — associated with worsened outcomes in cryptococcal meningitis. [1,30,31]","citation":[1,17,21,22,27,30,31],"next":"mening-blood-tests","treatment":{"firstLine":{"drug":"Amphotericin B liposomal + Flucytosine","dose":"Amphotericin B 3-4 mg/kg/day; Flucytosine 25 mg/kg","route":"Amphotericin B IV; Flucytosine PO","frequency":"Amphotericin B daily; Flucytosine q6h","duration":"Induction 1 week, then consolidation with Fluconazole 400-800 mg/day","notes":"NO corticosteroids - worsened outcomes; ID consultation required"},"monitoring":"Renal function and electrolytes daily (amphotericin nephrotoxicity); flucytosine levels if available; serial LPs for elevated ICP"},"summary":"HIV subacute: ampho + flucytosine — check OP","safetyLevel":"critical"}'::jsonb
WHERE id = 'mening-tx-crypto' AND tree_id = 'meningitis';

-- Node: mening-bacterial-mgmt (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Bacterial Meningitis — Tailored Management","body":"**Continue empiric antibiotics.** Await Gram stain, culture, and PCR for pathogen identification.\n\n**CSF Gram stain:** 60–99% sensitivity, 97–100% specificity. Sensitivity reduced after antibiotics. Negative Gram stain does NOT exclude bacterial meningitis. [5,14]\n\n**CSF culture:** Definitive diagnosis + antibiotic sensitivities. Sensitivity reduced **>30%** if LP performed >4 hours after antibiotics. *N. meningitidis* cultures may sterilize within 2 hours of antibiotics. [14]\n\n**CSF PCR:** Detects bacterial DNA even days after antibiotics — 87–100% sensitivity, 98–100% specificity. [12]\n\n**CSF lactate >35.1 mg/dL:** 93% sensitivity, 97% specificity for bacterial meningitis (when obtained before antibiotics). Particularly useful in healthcare-associated infections. [11]\n\n[Corticosteroid Guide](#/info/mening-steroid-guide) — continue dexamethasone for pneumococcal meningitis; discontinue if *Listeria* or *Cryptococcus* identified. [21][31]","citation":[5,11,12,14,21,31],"next":"mening-steroids"}'::jsonb
WHERE id = 'mening-bacterial-mgmt' AND tree_id = 'meningitis';

-- Node: mening-fungal-mgmt (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Fungal Meningitis Management","body":"Fungal meningitis is primarily a disease of **immunocompromised** populations. Most cases present **subacutely** with weeks of evolving symptoms. [8]\n\n**Most common cause:** *Cryptococcus neoformans* (~1 million cases/year in HIV/AIDS). [17]\n\nOther causes: *Histoplasma*, *Coccidioides*, *Candida* species.\n\n**Treatment (requires ID consultation):**\n• **Induction (1 week):** [Amphotericin B liposomal](#/drug/amphotericin-b/cryptococcal meningitis) 3–4 mg/kg/day IV + [Flucytosine](#/drug/flucytosine/cryptococcal meningitis) 25 mg/kg PO q6h [22,30]\n• **Consolidation:** [Fluconazole](#/drug/fluconazole/cryptococcal meningitis) 400–800 mg/day PO [22,30]\n• This regimen showed lowest mortality in a Cochrane review of 13 studies (2426 participants) [22]\n\n**⚠️ Do NOT give corticosteroids** — dexamethasone is associated with **worsened outcomes** in cryptococcal and listerial meningitis. Discontinue immediately if either pathogen identified. [1,21,30,31]","citation":[1,8,17,21,22,30,31],"next":"mening-dispo","treatment":{"firstLine":{"drug":"Amphotericin B liposomal + Flucytosine","dose":"Amphotericin B 3-4 mg/kg/day; Flucytosine 25 mg/kg","route":"Amphotericin B IV; Flucytosine PO","frequency":"Amphotericin B daily; Flucytosine q6h","duration":"Induction 1 week, then consolidation with Fluconazole 400-800 mg/day PO","notes":"ID consultation required; NO corticosteroids - discontinue if started empirically"},"monitoring":"Renal function and electrolytes daily; flucytosine levels if available; serial LPs for elevated ICP management"}}'::jsonb
WHERE id = 'mening-fungal-mgmt' AND tree_id = 'meningitis';

