-- Node: pe-renal-hepatic (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"Renal or Hepatic Impairment","body":"**CrCl <30 mL/min:**\n• [UFH](#/drug/ufh/pe) preferred — renally independent clearance\n• Adjust LMWH dose for CrCl 15–30 (enoxaparin 1 mg/kg SC daily)\n• Apixaban may be used cautiously (least renal elimination of DOACs)\n\n**Severe hepatic disease (Child-Pugh C):**\n• UFH preferred\n• DOACs contraindicated in severe hepatic impairment\n\n**HIT (heparin-induced thrombocytopenia):**\n• Discontinue ALL heparin products immediately\n• [Fondaparinux](#/drug/fondaparinux/pe) or argatroban as alternatives\n• Bridge to warfarin only after platelet recovery (>150k)","citation":[4,5],"treatment":{"firstLine":{"drug":"Unfractionated Heparin (UFH)","dose":"80 units/kg bolus, then 18 units/kg/hr","route":"IV","frequency":"Continuous infusion","duration":"Until transition to oral anticoagulation","notes":"Preferred for CrCl <30 mL/min and severe hepatic disease"},"alternative":{"drug":"Enoxaparin (dose-adjusted)","dose":"1 mg/kg daily","route":"SC","frequency":"Once daily","duration":"Until transition to oral anticoagulation","notes":"For CrCl 15-30 mL/min; avoid if CrCl <15"},"otherOption":{"drug":"Fondaparinux","dose":"5-10 mg (weight-based)","route":"SC","frequency":"Once daily","duration":"Until transition to oral anticoagulation","notes":"Alternative for HIT; use with caution if CrCl <30"},"monitoring":"aPTT q6h (UFH); anti-Xa levels for LMWH in renal impairment; platelets for HIT"},"summary":"CrCl <30 use UFH; severe hepatic use UFH; HIT: stop ALL heparin, use fondaparinux or argatroban","safetyLevel":"warning"}'::jsonb
WHERE id = 'pe-renal-hepatic' AND tree_id = 'pe-treatment';

-- Node: pph-initial-assess (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Hemodynamic Assessment","body":"Assess the patient **before** fixating on blood estimation:\n\n• Vital signs — HR, SBP, SpO₂, mental status\n• [Shock Index](#/calculator/shock-index) — HR/SBP ratio: ≥0.9 flags need for referral (sensitivity 100%); ≥1.4 urgent need for intervention; ≥1.7 high chance of adverse maternal outcome. Derived in low-resource settings (n=958), not yet prospectively validated [3]\n• Skin: pallor, cold, clammy, mottling\n• Urine output if catheterized\n\n**Pregnancy physiology obscures early shock.** Healthy peripartum patients compensate well — tachycardia and narrowed pulse pressure appear before hypotension. By the time SBP drops, blood loss is often ≥25% of blood volume (~1500 mL).\n\n**Use the shock index — it outperforms HR or SBP alone for detecting occult obstetric hemorrhage.** [3][4]","citation":[3,4],"options":[{"label":"Unstable — SI >1.0, SBP <90, or altered mental status","description":"Activate hemorrhage protocol NOW","next":"pph-unstable","urgency":"critical"},{"label":"Stable but actively bleeding","description":"Call team, initiate measures","next":"pph-call-team","urgency":"urgent"}],"summary":"Shock Index ≥0.9 refer, ≥1.4 urgent intervention, ≥1.7 high risk (El Ayadi 2016). Pregnancy masks early hypotension."}'::jsonb
WHERE id = 'pph-initial-assess' AND tree_id = 'pph';

-- Node: precip-oxytocin (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Oxytocin & Uterine Massage","body":"OXYTOCIN — POSTPARTUM UTEROTONIC\n\n**Preferred (IV access established):** [Oxytocin](#/drug/oxytocin/precipitous delivery) 20 units in 1L NS (or LR) at 250 mL/hr.\n\n**No IV access:** [Oxytocin](#/drug/oxytocin/precipitous delivery) 10 units IM into the anterolateral thigh — this is the WHO-preferred prophylactic route in low-resource or pre-IV settings. [8]\n\n**Do NOT give IV push** — can cause profound hypotension. [8]\n\n**Timing:** Start after the placenta is delivered. Do not wait to assess bleeding — **empiric oxytocin decreases postpartum hemorrhage risk.** [8]\n\nBIMANUAL UTERINE MASSAGE\n• Place one hand on the uterine fundus abdominally\n• Massage firmly until the uterus contracts and feels firm (\"boggy\" uterus = atony = hemorrhage risk)\n• Continue massage intermittently until uterine tone is maintained\n\n**Uterine atony is the #1 cause of postpartum hemorrhage.** Oxytocin + massage addresses this directly. [8]","citation":[8],"next":"precip-lacerations","treatment":{"firstLine":{"drug":"Oxytocin","dose":"20 units in 1L NS or LR","route":"IV infusion","frequency":"250 mL/hr (83 mL/hr = 10 mU/min)","duration":"until uterine tone maintained","notes":"Do NOT give IV push - causes profound hypotension. Start after placenta delivered. If no IV access: 10 units IM into anterolateral thigh (WHO-preferred IM dose)."},"alternative":{"drug":"Methylergonovine (Methergine)","dose":"0.2 mg","route":"IM","frequency":"q2-4h PRN","duration":"max 5 doses","notes":"CONTRAINDICATED in hypertension or preeclampsia. Second-line if oxytocin fails."},"otherOption":{"drug":"Misoprostol (Cytotec)","dose":"800-1000 mcg","route":"PR or SL","frequency":"once","duration":"single dose","notes":"Alternative uterotonic. Causes fever, shivering, diarrhea. No contraindication in HTN."},"monitoring":"Uterine tone (firm vs boggy), vaginal bleeding, vital signs q15 min x1 hour post-placenta."},"summary":"Oxytocin 20 units in 1L NS IV at 250 mL/hr (or 10 units IM if no IV access) — do NOT IV push, bimanual massage until firm uterine tone","safetyLevel":"critical"}'::jsonb
WHERE id = 'precip-oxytocin' AND tree_id = 'precip-delivery';

-- Node: rh-uterine-atony (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"Uterine Atony Management","body":"**UTERINE ATONY IS NEAR-UNIVERSAL AFTER RH.**\n\nThe uterus has been cut, the patient was in arrest with no myometrial tone, and postpartum hemorrhage is nearly certain.\n\n**FIRST-LINE — UTEROTONICS (start all that apply):**\n\n• **[Oxytocin](#/drug/oxytocin/postpartum hemorrhage)** — 20 units in 1L NS IV at 250 mL/hr (do NOT give IV push — profound hypotension)\n• **[Tranexamic Acid (TXA)](#/drug/tranexamic-acid/postpartum hemorrhage)** — 1 g IV over 10 minutes, repeat once at 30 min if bleeding continues (WOMAN trial — give within 3 hours)\n• **Bimanual uterine massage** — one hand in vagina, one on fundus, compress continuously\n\n**SECOND-LINE (if atony persists):**\n\n• **[Misoprostol](#/drug/misoprostol/postpartum hemorrhage)** — 800-1000 mcg PR (rectal) or SL\n• [Methylergonovine](#/drug/methylergonovine/postpartum hemorrhage) (Methergine) — 0.2 mg IM (CONTRAINDICATED in hypertension, preeclampsia, eclampsia — this patient very possibly qualifies; be cautious)\n• [Carboprost](#/drug/carboprost/postpartum hemorrhage) (Hemabate) — 250 mcg IM q15 min (CONTRAINDICATED in asthma)\n\n**THIRD-LINE (refractory PPH):**\n\n• **Uterine balloon tamponade** (Bakri, Ebb, or Foley)\n• **Surgical management** in OR — uterine artery ligation, B-Lynch suture, hysterectomy\n• **Interventional radiology** — uterine artery embolization\n\n**KEEP THE BLOOD PRODUCTS COMING.** Continue MTP — 1:1:1 ratio (pRBC:FFP:platelets). Goal: fibrinogen >200, platelets >50, Ca++ >1.0.","citation":[1,2,19,20],"next":"rh-disposition","treatment":{"firstLine":{"drug":"Oxytocin","dose":"20 units in 1L NS","route":"IV infusion","frequency":"250 mL/hr (never IV push)","duration":"until atony resolves and 4+ hours post-delivery","notes":"Do NOT give IV push — causes profound hypotension and arrhythmia."},"alternative":{"drug":"Tranexamic Acid (TXA)","dose":"1 g IV over 10 min","route":"IV","frequency":"repeat once at 30 min if bleeding continues","duration":"single dose (or 2-dose regimen)","notes":"WOMAN trial — give within 3 hours of delivery. Reduces maternal mortality from bleeding."},"otherOption":{"drug":"Misoprostol","dose":"800-1000 mcg","route":"PR (rectal) or SL","frequency":"once","duration":"single dose","notes":"Alternative uterotonic. Side effects: fever, shivering, diarrhea. No contraindication in HTN."},"monitoring":"Uterine tone (firm vs. boggy), vaginal bleeding, fibrinogen, platelets, calcium, vital signs. Continue MTP with 1:1:1 ratio until hemostasis achieved."},"summary":"Oxytocin drip + TXA 1g IV + bimanual massage first-line. Misoprostol, methergine (not in HTN), carboprost (not asthma) 2nd-line.","safetyLevel":"critical"}'::jsonb
WHERE id = 'rh-uterine-atony' AND tree_id = 'resuscitative-hysterotomy';

-- Node: sal-acute-dose (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Acute Ingestion — Dose Estimation","body":"Estimate the ingested dose (mg/kg) from history. If uncertain, assume worst case.\n\n**Oil of wintergreen warning:** 1 mL of methyl salicylate = ~1,400 mg aspirin. A single teaspoon (~5 mL) = ~7,000 mg — potentially lethal in a child. [1][3][15][22]\n\n**Enteric-coated tablets:** Peak absorption may be delayed 12-24 hours. Extended observation required. [18][22]\n\nOut-of-hospital consensus: refer for ED evaluation if >150 mg/kg or >6.5 g ingested. [23]\n\nEstimated dose:","citation":[1,3,9,15,18,22,23],"options":[{"label":"< 150 mg/kg (minimal risk)","next":"sal-mild-observe"},{"label":"150-300 mg/kg (moderate)","next":"sal-moderate-risk"},{"label":"> 300 mg/kg or Unknown Large Ingestion","next":"sal-severe-risk","urgency":"critical"}],"summary":"Estimate mg/kg dose — oil of wintergreen is 1400mg/mL; enteric-coated delays peak 12-24hr","safetyLevel":"warning"}'::jsonb
WHERE id = 'sal-acute-dose' AND tree_id = 'salicylate';

-- Node: sal-seizure (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Seizures / Severe Altered Mental Status","body":"**Benzodiazepines first-line for seizures:**\n• [Lorazepam](#/drug/lorazepam/status epilepticus) 0.1 mg/kg IV (max 4 mg)\n• [Midazolam](#/drug/midazolam/status epilepticus) 0.2 mg/kg IM (max 10 mg) if no IV access [24]\n\n**Empiric dextrose:** [Dextrose](#/drug/dextrose/neuroglycopenia) D50W 50 mL IV — even with NORMAL serum glucose. Salicylate uncouples oxidative phosphorylation, causing massive CNS glucose consumption (**neuroglycopenia**). CSF glucose drops before serum glucose. [2][4][17]\n\n**Seizures in salicylate toxicity = severe poisoning.** This patient almost certainly needs hemodialysis. [5][15]","citation":[1,2,3,4,5,15,17,22,24],"next":"sal-airway-warning","treatment":{"firstLine":{"drug":"Lorazepam","dose":"0.1 mg/kg IV (max 4 mg)","route":"IV push","frequency":"May repeat once in 5-10 min","duration":"Single dose for seizure termination","notes":"Push over 2 min. Have airway equipment ready. Seizures indicate severe toxicity requiring HD."},"alternative":{"drug":"Midazolam","dose":"0.2 mg/kg IM (max 10 mg)","route":"IM","frequency":"Single dose","duration":"One-time if no IV access","notes":"Use if no IV access. IM onset 5 min. Also give empiric D50W for neuroglycopenia."},"monitoring":"Respiratory status. Mental status. Fingerstick glucose. This patient needs emergent nephrology consult for hemodialysis."},"summary":"BZD for seizures, empiric D50W even with normal glucose (neuroglycopenia) — seizures = severe, needs HD","safetyLevel":"critical"}'::jsonb
WHERE id = 'sal-seizure' AND tree_id = 'salicylate';

