UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"GI Decontamination","body":"Activated charcoal effectively adsorbs salicylate. Salicylate''s delayed gastric emptying may extend the window of efficacy. [1][3][7]\n\nDo NOT induce emesis. Gastric lavage is rarely indicated. [7][15][18][23]\n\nTime since ingestion and formulation:","citation":[1,3,7,15,18,19,20,23],"options":[{"label":"Within 1-2 Hours, Alert Patient","next":"sal-charcoal"},{"label":"Enteric-Coated, Massive Ingestion, or Bezoar Suspected","next":"sal-mdac"},{"label":"> 2 Hours, Contraindicated, or Chronic Exposure","next":"sal-alkalinize-start"}],"summary":"Charcoal effective for salicylates with extended window (2-4hr) due to delayed gastric emptying"}'::jsonb
