-- Node: se-peds (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Pediatric Considerations","body":"**Same treatment algorithm as adults** — BZD first-line, then 2nd-line ASM, then anesthetic infusions.\n\n**BZD dosing (weight-based):**\n• IV [Lorazepam](#/drug/lorazepam/status epilepticus): 0.1 mg/kg (max 4 mg), repeat × 1\n• IM [Midazolam](#/drug/midazolam/status epilepticus): 13-40 kg → 5 mg; ≥40 kg → 10 mg (0.2 mg/kg, max 10 mg)\n• Rectal [Diazepam](#/drug/diazepam/status epilepticus): 0.2-0.5 mg/kg (max 20 mg)\n\n**2nd-line ASM:** Same agents and weight-based dosing as adults (per ESETT, which included pediatric patients).\n• EcLiPSE and ConSEPT trials confirmed levetiracetam and phenytoin are equivalent in pediatric convulsive SE\n\n**Pediatric-specific considerations:**\n• **Pyridoxine-dependent epilepsy** (age <2 yr): Give [Pyridoxine](#/drug/pyridoxine/pyridoxine dependent epilepsy) 100 mg IV if SE is refractory and no clear etiology — especially neonates with refractory seizures\n• **Febrile SE:** Most common etiology in children — workup directed at fever source\n• **Inborn errors of metabolism:** Consider in neonates/infants with unexplained SE\n• [Phenobarbital](#/drug/phenobarbital/status epilepticus) remains first-line for neonatal seizures\n\n**Weight estimation:** <1 yr: (months × 0.5) + 3.5 kg | 1-10 yr: (years × 2) + 10 kg | >10 yr: (years × 2) + 20 kg","citation":[1,2,6],"next":"se-2nd-line-choice","treatment":{"firstLine":{"drug":"Lorazepam (pediatric)","dose":"0.1 mg/kg IV (max 4 mg)","route":"IV","frequency":"May repeat once","duration":"Push over 2 min","notes":"Same algorithm as adults. Weight-based dosing."},"alternative":{"drug":"Midazolam (pediatric)","dose":"0.2 mg/kg IM (max 10 mg); 13-40 kg: 5 mg, >=40 kg: 10 mg","route":"IM","frequency":"Single dose","duration":"Immediate","notes":"Use when no IV access. Rectal diazepam 0.2-0.5 mg/kg (max 20 mg) also acceptable."},"otherOption":{"drug":"Pyridoxine (neonates/infants)","dose":"100 mg IV","route":"IV","frequency":"Single dose","duration":"Immediate","notes":"Consider in refractory SE age <2 yr with no clear etiology. Rule out pyridoxine-dependent epilepsy."},"monitoring":"Weight estimation formulas provided. Febrile SE most common in children. Phenobarbital first-line for neonatal seizures."},"summary":"Same algorithm as adults with weight-based dosing — consider pyridoxine-dependent epilepsy in neonates/infants"}'::jsonb
WHERE id = 'se-peds' AND tree_id = 'status-epilepticus';

-- Node: stemi-p2y12 (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"P2Y12 Inhibitor Selection","body":"Load with ONE P2Y12 inhibitor before or at time of PCI. Discuss with interventional cardiologist.\n\n**[Prasugrel](#/drug/prasugrel/acs)** 60 mg loading → 10 mg daily\n• More potent platelet inhibition, lower ischemic events vs clopidogrel; ticagrelor and prasugrel are Class I equivalents (no preference) in 2025 ACC/AHA [18][23]\n• **CONTRAINDICATED:** prior stroke/TIA — basis: TRITON-TIMI 38 (n=13,608), where patients with prior stroke/TIA had net clinical harm with prasugrel [37]\n• **No benefit:** age >75y, weight <60 kg — basis: TRITON-TIMI 38 prespecified subgroups showing no net clinical benefit [37]\n\n**[Ticagrelor](#/drug/ticagrelor/acs)** 180 mg loading → 90 mg BID\n• Fewer stent thromboses and lower death rate vs clopidogrel [19]\n• Higher stroke/ICH risk vs clopidogrel [19]\n\n**[Clopidogrel](#/drug/clopidogrel/acs)** 600 mg loading → 75 mg daily\n• Variable metabolism (CYP2C19) [20]\n• Use if CI to prasugrel AND ticagrelor, or high bleeding risk [5][23]\n\n**2025 ACC/AHA update:** Ticagrelor AND prasugrel are now Class I without distinction in PCI-managed STEMI; clopidogrel is the recommended concurrent P2Y12 agent for fibrinolytic-managed STEMI. [5][23]","citation":[5,18,19,20,23,37],"options":[{"label":"Prasugrel or Ticagrelor (Class I, equivalent per 2025 ACC/AHA)","description":"PCI-bound patients. Avoid prasugrel if prior stroke/TIA.","next":"stemi-anticoag"},{"label":"Clopidogrel (for fibrinolysis OR if prasugrel/ticagrelor CI)","description":"2025 ACC/AHA: clopidogrel is the P2Y12 agent for fibrinolytic-managed STEMI.","next":"stemi-anticoag"}],"treatment":{"firstLine":{"drug":"Prasugrel","dose":"60 mg loading, then 10 mg","route":"PO","frequency":"Once for loading, then daily","duration":"12 months DAPT","notes":"CONTRAINDICATED if prior stroke/TIA. No benefit if age >75y or weight <60 kg."},"alternative":{"drug":"Ticagrelor","dose":"180 mg loading, then 90 mg","route":"PO","frequency":"Once for loading, then BID","duration":"12 months DAPT","notes":"Higher stroke/ICH risk vs clopidogrel. Fewer stent thromboses than clopidogrel."},"otherOption":{"drug":"Clopidogrel","dose":"600 mg loading, then 75 mg","route":"PO","frequency":"Once for loading, then daily","duration":"12 months DAPT","notes":"Variable metabolism (CYP2C19). Use if CI to prasugrel AND ticagrelor, or high bleeding risk."},"monitoring":"Monitor for bleeding complications. DAPT for 12 months post-PCI. Discuss with interventional cardiologist."},"summary":"Prasugrel and ticagrelor Class I equivalent for PCI (2025 ACC/AHA); clopidogrel for fibrinolysis or if others CI","safetyLevel":"warning"}'::jsonb
WHERE id = 'stemi-p2y12' AND tree_id = 'stemi';

-- Node: stemi-anticoag (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Anticoagulation","body":"**For primary PCI:**\n• [UFH](#/drug/ufh/stemi) 70–100 units/kg IV bolus (without GP IIb/IIIa) OR 50–70 units/kg (with GP IIb/IIIa)\n• [Bivalirudin](#/drug/bivalirudin/pci) 0.75 mg/kg IV bolus then 1.75 mg/kg/hr — preferred if high bleeding risk\n\n**For fibrinolytic therapy** (minimum 48 hours):\n• [UFH](#/drug/ufh/stemi) weight-based bolus + infusion\n• [Enoxaparin](#/drug/enoxaparin/stemi) — alternative (age-adjusted dosing)\n• [Fondaparinux](#/drug/fondaparinux/stemi) 2.5 mg SC daily — alternative\n\nSee [Anticoagulation Details](#/info/stemi-anticoag-detail)","citation":[5,8,23],"next":"stemi-reperfusion-q","treatment":{"firstLine":{"drug":"Unfractionated Heparin (UFH)","dose":"70-100 units/kg IV bolus (without GP IIb/IIIa) OR 50-70 units/kg (with GP IIb/IIIa)","route":"IV","frequency":"Bolus for PCI","duration":"During PCI procedure","notes":"For primary PCI. ACT-guided dosing in cath lab."},"alternative":{"drug":"Bivalirudin","dose":"0.75 mg/kg IV bolus, then 1.75 mg/kg/hr","route":"IV","frequency":"Bolus then infusion","duration":"During and post-PCI","notes":"Preferred if high bleeding risk. Direct thrombin inhibitor."},"monitoring":"ACT during PCI. Monitor for bleeding. For fibrinolysis: anticoagulation minimum 48 hours."},"summary":"UFH 70-100 units/kg for PCI; bivalirudin if high bleeding risk; enoxaparin for fibrinolysis"}'::jsonb
WHERE id = 'stemi-anticoag' AND tree_id = 'stemi';

-- Node: stemi-lytics (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":4,"title":"Fibrinolytic Therapy","body":"**Door-to-needle ≤30 minutes.** Fibrin-specific agents preferred.\n\nCheck [Fibrinolytic Contraindications](#/info/stemi-lytic-contraindications)\n\n**Agents** (see [Fibrinolytic Dosing](#/info/stemi-lytic-agents)):\n• [Tenecteplase](#/drug/tenecteplase/stemi) — single weight-based IV bolus (preferred)\n• [Alteplase](#/drug/alteplase/stemi) — accelerated 90-min regimen\n• [Reteplase](#/drug/reteplase/stemi) — 10 + 10 unit double bolus\n\n**Age >75 years:** Consider half-dose tenecteplase (reduced ICH risk) — basis: STREAM-1 amended its protocol to half-dose TNK in patients ≥75y after excess ICH [22] (pooled STREAM analysis: ICH 7.1% with full dose vs 0% with half dose in ≥75y [38]); STREAM-2 randomized patients ≥60y to half-dose TNK with preserved reperfusion efficacy [33]; ACEP Level C also supports dose reduction in the elderly [21]\n\n**After fibrinolysis:** Transfer to PCI center. Angiography within 3–24 hours (NOT within first 2–3 hours). [5][8][23]\n\nAny contraindications to fibrinolysis?","citation":[5,8,21,22,23,33,38],"options":[{"label":"No contraindications — give fibrinolytic","next":"stemi-post-lytics"},{"label":"Absolute contraindication","description":"Must transfer for PCI regardless of time","next":"stemi-transfer","urgency":"critical"},{"label":"Relative contraindication","description":"Weigh risks vs benefits, consider transfer","next":"stemi-transfer","urgency":"urgent"}],"treatment":{"firstLine":{"drug":"Tenecteplase","dose":"Weight-based: <60kg: 30mg | 60-69kg: 35mg | 70-79kg: 40mg | 80-89kg: 45mg | >=90kg: 50mg","route":"IV bolus","frequency":"Single dose","duration":"One-time administration","notes":"Preferred fibrinolytic. Consider half-dose if age >75 years (reduced ICH risk)."},"alternative":{"drug":"Alteplase","dose":"15 mg IV bolus, then 0.75 mg/kg over 30 min (max 50 mg), then 0.5 mg/kg over 60 min (max 35 mg)","route":"IV","frequency":"Accelerated 90-min regimen","duration":"Total 90 minutes","notes":"Total dose not to exceed 100 mg."},"monitoring":"Continuous cardiac monitoring. Monitor for reperfusion signs: pain resolution, >50% ST resolution within 60-90 min, reperfusion arrhythmias. Watch for bleeding complications."},"summary":"Door-to-needle ≤30 min — tenecteplase preferred; half-dose if >75y; check contraindications first","safetyLevel":"critical"}'::jsonb
WHERE id = 'stemi-lytics' AND tree_id = 'stemi';

